protocol RunbookFix {
  roles User, Planner, Researcher, Web, Approver, Executor, Shell;

  User -> Planner : Task(str) where len <= 2000;

  // Planner selects the runbook using only the enum of allowed runbook IDs.
  call Planner -> Researcher : Query(enum{rb_101, rb_118, rb_204, rb_233, rb_305, rb_342, rb_417, rb_456, rb_512, rb_577}) returns unit;
  Researcher -> Web : Get(enum{rb_101, rb_118, rb_204, rb_233, rb_305, rb_342, rb_417, rb_456, rb_512, rb_577});
  Web -> Researcher : Page(str);

  // Researcher passes back only a low-capacity enum (no taint propagates to Planner).
  Researcher -> Planner : Recommend(enum{df_h, du_var_log, free_m, uptime, ls_var_log});

  // Planner proposes only an enum command; Approver is the endorser that gates execution.
  Planner -> Approver : Propose(enum{df_h, du_var_log, free_m, uptime, ls_var_log});

  choice at Approver {
    Approver -> Executor : Approved(enum{df_h, du_var_log, free_m, uptime, ls_var_log});
    call Executor -> Shell : Exec(enum{df_h, du_var_log, free_m, uptime, ls_var_log}) returns str;
    Executor -> Planner : Result(str) where len <= 4000;
  } or {
    Approver -> Planner : Denied;
  }

  Planner -> User : Report(str) where len <= 4000;
  end;
}

